<script setup lang="ts">
import { computed, ref } from 'vue'
import { useToast } from 'vuestic-ui'
import api from '../../../services/api'
import { useUserStore } from '../../../stores/user-store'
import { OpsUserRole } from '../../ops-users/types'
import { useFormat } from '../../../composables/useFormat'
import { OrderStatus, type OrderCancellation, type VnOrder } from '../types'
import {
    actualRefund,
    cancellationErrorMessage,
    canForceCancellation,
    canReviewCancellation,
    parseRefundAmount,
    refundValidation,
    suggestedRefund,
    supportsCancellation,
} from '../cancellation'

const props = defineProps<{ order: VnOrder }>()
const emit = defineEmits<{
    (event: 'updated', order: VnOrder): void
    (event: 'changed'): void
    (event: 'busy', busy: boolean): void
}>()
const user = useUserStore()
const isAdmin = computed(() => user.userRole === OpsUserRole.Admin)
const { init: notify } = useToast()
const { formatDateTimeV } = useFormat()
const pending = computed(() => props.order.cancellations?.find((request) => request.status === 'pending'))
const reviewed = computed(() => props.order.cancellations?.filter((request) => request.status !== 'pending') ?? [])
const suggestion = computed(() => suggestedRefund(props.order, pending.value))
const showModal = ref(false)
const mode = ref<'review' | 'force'>('review')
const decision = ref<'approve' | 'reject'>('approve')
const refundEnabled = ref(true)
const amountInput = ref('')
const refundReason = ref('')
const cancelReason = ref('')
const rejectReason = ref('')
const busy = ref(false)
const needsRefresh = ref(false)
const errorMessage = ref('')
const amount = computed(() => (refundEnabled.value ? parseRefundAmount(amountInput.value) : 0))
const difference = computed(() =>
    amount.value !== null && suggestion.value !== null ? amount.value - suggestion.value : null,
)
const actionAllowed = computed(
    () =>
        isAdmin.value &&
        (mode.value === 'force' ? canForceCancellation(props.order) : canReviewCancellation(props.order)),
)
const validation = computed(() => {
    if (!actionAllowed.value) return '此訂單目前無法執行這項操作，請確認最新審核結果。'
    if (mode.value === 'review' && decision.value === 'reject')
        return rejectReason.value.trim() ? '' : '請填寫駁回原因。'
    if (mode.value === 'force' && !cancelReason.value.trim()) return '請填寫取消原因。'
    return refundValidation(amount.value, suggestion.value, refundReason.value)
})
const formatAmount = (value: number | null) => (value === null ? '未提供' : `${value.toLocaleString('en-US')} VND`)
const formatDifference = (value: number | null) =>
    value === null ? '未提供' : `${value > 0 ? '+' : ''}${formatAmount(value)}`
const formatTime = (value?: string | null) => (value ? `${formatDateTimeV(Number(value))}（越南時間）` : '未提供')
const requester = (request: OrderCancellation) => {
    if (request.source === 'admin') {
        return `Admin #${request.requesterOpsUserInfoId ?? request.reviewerOpsUserInfoId ?? '未提供'}`
    }
    const name = props.order.userInfo?.nickname || props.order.userInfo?.firstName || '使用者'
    return `${name}（使用者 #${request.requesterUserInfoId ?? props.order.userInfoId}）`
}
const auditDifference = (request: OrderCancellation) => {
    const actual = actualRefund(props.order, request)
    const suggested = suggestedRefund(props.order, request)
    return actual !== null && suggested !== null ? actual - suggested : null
}
const adjustmentReason = (request: OrderCancellation) =>
    request.refundReason ||
    props.order.refunds?.find((refund) => refund.cancellationRequestId === request.id)?.reason ||
    '未提供'
const setBusy = (value: boolean) => {
    busy.value = value
    emit('busy', value)
}
const loadLatest = async () => {
    const { data } = await api.getOrderDetail(props.order.id)
    if (data.code !== 'success' || !data.data) throw new Error('Order not found')
    emit('updated', data.data)
    needsRefresh.value = false
}
const refresh = async () => {
    if (busy.value) return
    setBusy(true)
    try {
        await loadLatest()
        errorMessage.value = ''
    } catch {
        needsRefresh.value = true
        errorMessage.value = '無法重新載入訂單。確認最新資料前，已暫停審核及退款操作。'
    } finally {
        setBusy(false)
    }
}
const open = (nextMode: 'review' | 'force') => {
    if (!isAdmin.value || busy.value || needsRefresh.value) return
    if (nextMode === 'review' ? !canReviewCancellation(props.order) : !canForceCancellation(props.order)) return
    mode.value = nextMode
    decision.value = 'approve'
    refundEnabled.value = true
    amountInput.value = suggestion.value === null ? '' : String(suggestion.value)
    refundReason.value = ''
    cancelReason.value = ''
    rejectReason.value = ''
    errorMessage.value = ''
    showModal.value = true
}
const toggleRefund = (enabled: boolean) => {
    refundEnabled.value = enabled
    if (enabled) amountInput.value = suggestion.value === null ? '' : String(suggestion.value)
}
const beforeClose = (hide: () => unknown) => {
    if (!busy.value) hide()
}
const submit = async () => {
    if (busy.value || needsRefresh.value || validation.value) return
    setBusy(true)
    errorMessage.value = ''
    needsRefresh.value = true
    let succeeded = false
    try {
        if (mode.value === 'review' && decision.value === 'reject') {
            await api.rejectOrderCancellation(props.order.id, rejectReason.value.trim())
        } else {
            const payload = {
                refundAmount: amount.value!,
                // 舊 API 一律要求 refundReason；等額退款沿用取消原因，不要求 Admin 重複填寫。
                refundReason:
                    refundReason.value.trim() ||
                    (mode.value === 'force' ? cancelReason.value.trim() : pending.value?.reason) ||
                    '依建議退款額退回 V Coin',
            }
            if (mode.value === 'force')
                await api.forceOrderCancellation(props.order.id, { ...payload, reason: cancelReason.value.trim() })
            else await api.approveOrderCancellation(props.order.id, payload)
        }
        succeeded = true
        showModal.value = false
        notify({ message: decision.value === 'reject' ? '已駁回取消申請' : '訂單已取消', color: 'success' })
    } catch (error) {
        errorMessage.value = cancellationErrorMessage(error)
        // 舊版路由會在金額為 0 時直接回傳 schema error。
        const status = (error as { response?: { status?: number } })?.response?.status
        if (status === 400 && amount.value === 0 && decision.value !== 'reject') {
            errorMessage.value += ' 目前後端可能尚未支援 0 元退款。'
        }
    }
    try {
        // 成功、業務衝突、逾時都重新讀取，避免回應遺失後盲目再送造成重複操作。
        await loadLatest()
    } catch {
        errorMessage.value = `${
            succeeded ? '操作已完成。' : errorMessage.value
        } 無法更新訂單資料，請重新載入後確認結果。`
    } finally {
        emit('changed')
        setBusy(false)
    }
}
</script>

<template>
    <section v-if="isAdmin && supportsCancellation(order)" class="cancellation-panel my-4" aria-label="訂單取消與退款">
        <VaAlert v-if="errorMessage && !showModal" color="danger" class="mb-3">{{ errorMessage }}</VaAlert>
        <VaButton v-if="needsRefresh" preset="secondary" :loading="busy" :disabled="busy" @click="refresh"
            >重新載入訂單</VaButton
        >
        <div v-if="pending" class="cancellation-panel__pending p-4 rounded mb-3">
            <h2 class="font-bold mb-2">申請取消 · 退款審核中</h2>
            <dl class="audit-grid">
                <dt>申請時間</dt>
                <dd>{{ formatTime(pending.createdAt) }}</dd>
                <dt>申請來源</dt>
                <dd>{{ pending.source === 'user' ? '使用者' : 'Admin' }}</dd>
                <dt>申請人</dt>
                <dd>{{ requester(pending) }}</dd>
                <dt>取消原因</dt>
                <dd>{{ pending.reason }}</dd>
                <dt>其他說明</dt>
                <dd>{{ pending.otherReason || '未提供' }}</dd>
                <dt>建議退款額</dt>
                <dd>{{ formatAmount(suggestion) }}</dd>
            </dl>
            <VaButton
                v-if="canReviewCancellation(order)"
                class="mt-3"
                :disabled="busy || needsRefresh"
                @click="open('review')"
                >審核取消申請</VaButton
            >
        </div>
        <VaButton
            v-if="canForceCancellation(order)"
            color="danger"
            preset="secondary"
            :disabled="busy || needsRefresh"
            @click="open('force')"
            >主動取消訂單</VaButton
        >
        <article v-for="request in reviewed" :key="request.id" class="p-4 rounded border mb-3">
            <h2 class="font-bold mb-2">{{ request.status === 'approved' ? '已取消' : '取消申請已駁回' }} · 審核紀錄</h2>
            <dl class="audit-grid">
                <dt>申請來源</dt>
                <dd>{{ request.source === 'user' ? '使用者' : 'Admin 主動取消' }}</dd>
                <dt>申請人</dt>
                <dd>{{ requester(request) }}</dd>
                <dt>申請時間</dt>
                <dd>{{ formatTime(request.createdAt) }}</dd>
                <dt>取消原因</dt>
                <dd>{{ request.reason }}</dd>
                <dt>其他說明</dt>
                <dd>{{ request.otherReason || '未提供' }}</dd>
                <dt v-if="request.status === 'rejected'">駁回原因</dt>
                <dd v-if="request.status === 'rejected'">{{ request.rejectReason || '未提供' }}</dd>
                <dt>建議退款額{{ request.suggestedRefundAmount == null ? '（依付款資料）' : '' }}</dt>
                <dd>{{ formatAmount(suggestedRefund(order, request)) }}</dd>
                <dt>實際退款額</dt>
                <dd>{{ formatAmount(actualRefund(order, request)) }}</dd>
                <template v-if="request.status === 'approved'">
                    <dt>差額</dt>
                    <dd>{{ formatDifference(auditDifference(request)) }}</dd>
                    <dt>退款調整原因</dt>
                    <dd>{{ adjustmentReason(request) }}</dd>
                </template>
                <dt>審核者</dt>
                <dd>{{ request.reviewerOpsUserInfoId ? `Admin #${request.reviewerOpsUserInfoId}` : '未提供' }}</dd>
                <dt>審核時間</dt>
                <dd>{{ formatTime(request.reviewedAt) }}</dd>
                <dt v-if="request.reviewNote">審核備註</dt>
                <dd v-if="request.reviewNote">{{ request.reviewNote }}</dd>
            </dl>
        </article>
        <p v-if="order.status === OrderStatus.CANCEL_COMPLETED && !reviewed.length" class="mt-3">
            訂單已取消，無法再次退款；尚未取得審核紀錄。
        </p>
        <VaModal
            v-model="showModal"
            size="small"
            mobile-fullscreen
            hide-default-actions
            close-button
            :before-cancel="beforeClose"
        >
            <h2 class="va-h5 mb-4">{{ mode === 'force' ? '主動取消訂單' : '審核取消申請' }} #{{ order.id }}</h2>
            <VaAlert v-if="errorMessage" color="danger" class="mb-3">{{ errorMessage }}</VaAlert>
            <div class="flex flex-col gap-4">
                <VaButtonToggle
                    v-if="mode === 'review'"
                    v-model="decision"
                    :disabled="busy || needsRefresh"
                    :options="[
                        { label: '核准取消', value: 'approve' },
                        { label: '駁回申請', value: 'reject' },
                    ]"
                />
                <VaTextarea
                    v-if="mode === 'review' && decision === 'reject'"
                    v-model="rejectReason"
                    label="駁回原因（必填）"
                    :disabled="busy || needsRefresh"
                />
                <template v-else>
                    <VaTextarea
                        v-if="mode === 'force'"
                        v-model="cancelReason"
                        label="取消原因（必填）"
                        :disabled="busy || needsRefresh"
                    />
                    <VaCheckbox
                        :model-value="refundEnabled"
                        label="退回 V Coin"
                        :disabled="busy || needsRefresh"
                        @update:modelValue="toggleRefund"
                    />
                    <VaInput
                        v-if="refundEnabled"
                        v-model="amountInput"
                        label="實際退款額（完整 VND 整數）"
                        inputmode="numeric"
                        :disabled="busy || needsRefresh"
                    />
                    <p class="text-sm">1 V Coin = 1 VND。請輸入完整金額，例如 100000。</p>
                    <dl class="audit-grid">
                        <dt>建議退款額</dt>
                        <dd>{{ formatAmount(suggestion) }}</dd>
                        <dt>實際退款額</dt>
                        <dd>{{ formatAmount(amount) }}</dd>
                        <dt>差額（實際 − 建議）</dt>
                        <dd>{{ formatDifference(difference) }}</dd>
                    </dl>
                    <VaAlert v-if="difference !== null && difference > 0" color="warning" role="alert"
                        >實際退款額超過建議退款額，多出的 {{ formatAmount(difference) }} 屬於平台補償，將一併加入使用者
                        V Coin 餘額。</VaAlert
                    >
                    <VaTextarea
                        v-model="refundReason"
                        :label="difference !== 0 ? '退款調整原因（必填）' : '退款調整原因（選填）'"
                        :disabled="busy || needsRefresh"
                    />
                    <p class="text-sm">確認後將取消訂單，並退回上述 V Coin；完成後不可再次退款。</p>
                </template>
                <p v-if="validation" role="status" class="text-sm">{{ validation }}</p>
                <div class="flex gap-2 justify-end">
                    <VaButton preset="secondary" :disabled="busy" @click="showModal = false">返回</VaButton>
                    <VaButton v-if="needsRefresh" :loading="busy" :disabled="busy" @click="refresh"
                        >重新載入訂單</VaButton
                    >
                    <VaButton
                        color="danger"
                        :loading="busy"
                        :disabled="busy || needsRefresh || !!validation"
                        @click="submit"
                        >{{ decision === 'reject' ? '確認駁回' : '確認取消訂單' }}</VaButton
                    >
                </div>
            </div>
        </VaModal>
    </section>
</template>

<style scoped>
.cancellation-panel__pending {
    background: var(--va-background-element);
    border-left: 4px solid var(--va-warning);
}
.audit-grid {
    display: grid;
    grid-template-columns: minmax(7rem, 1fr) 2fr;
    gap: 0.5rem 1rem;
    font-size: 0.875rem;
}
.audit-grid dt {
    font-weight: 600;
}
.audit-grid dd {
    overflow-wrap: anywhere;
    white-space: pre-wrap;
}
</style>
