import { OrderStatus, ServiceCategoryBackend, type OrderCancellation, type VnOrder } from './types'

const supportedServices: string[] = [
    ServiceCategoryBackend.ESCORT,
    ServiceCategoryBackend.SHUTTLE,
    ServiceCategoryBackend.CHARTER,
    ServiceCategoryBackend.MASSAGE,
    ServiceCategoryBackend.TUTOR,
]

export const supportsCancellation = (order: VnOrder) => supportedServices.includes(order.type)

export const canReviewCancellation = (order: VnOrder) =>
    supportsCancellation(order) &&
    order.status === OrderStatus.CANCEL_PENDING &&
    order.cancellations?.some((request) => request.status === 'pending') === true

export const canForceCancellation = (order: VnOrder) =>
    supportsCancellation(order) &&
    order.status === OrderStatus.COMPLETED &&
    Array.isArray(order.cancellations) &&
    order.cancellations.length === 0

const validAmount = (value: unknown): value is number =>
    typeof value === 'number' && Number.isSafeInteger(value) && value >= 0

// 舊 API 的 refundableAmount 是完整 VND 已付額扣除退款；不可加總 detail.payment，
// 其中綠界交易可能已換算為 TWD。優先使用取消申請的快照。
export const suggestedRefund = (order: VnOrder, request?: OrderCancellation): number | null => {
    const snapshot = request?.suggestedRefundAmount ?? order.suggestedRefundAmount
    if (validAmount(snapshot)) return snapshot
    if (
        typeof order.refundableAmount === 'number' &&
        Number.isSafeInteger(order.refundableAmount) &&
        validAmount(order.refundedAmount)
    ) {
        const amount = order.refundableAmount + order.refundedAmount
        return validAmount(amount) ? amount : null
    }
    return null
}

export const actualRefund = (order: VnOrder, request: OrderCancellation): number | null => {
    if (validAmount(request.refundAmount)) return request.refundAmount
    if (request.status === 'rejected') return 0
    const refunds = order.refunds?.filter((refund) => refund.cancellationRequestId === request.id)
    // 舊 API 沒有退款紀錄時不能推斷是 0；可能尚未提供完整資料。
    return refunds?.length ? refunds.reduce((total, refund) => total + Number(refund.amount), 0) : null
}

export const parseRefundAmount = (input: string): number | null => {
    if (!/^\d+$/.test(input.trim())) return null
    const amount = Number(input)
    return validAmount(amount) ? amount : null
}

export const refundValidation = (amount: number | null, suggested: number | null, reason: string): string => {
    if (suggested === null) return '無法取得建議退款額，請重新載入訂單。'
    if (amount === null) return '請輸入非負整數 VND 金額。'
    if (amount !== suggested && !reason.trim()) return '實際退款額與建議退款額不同，請填寫退款調整原因。'
    return ''
}

const errorMessages: Record<string, string> = {
    'auth/user-is-not-admin': '沒有取消審核權限，請以 Admin 帳號登入。',
    'auth/user-no-permission': '沒有取消審核權限，請以 Admin 帳號登入。',
    'order-cancellation/order-not-found': '訂單不存在，請重新整理列表。',
    'order-cancellation/no-pending-request': '此訂單已無待審核申請，請確認最新審核結果。',
    'order-cancellation/already-reviewed': '此申請已由其他管理員完成審核。',
    'order-cancellation/force-not-allowed': '目前訂單狀態不允許主動取消，請確認最新資料。',
    'order-cancellation/reject-reason-required': '請填寫駁回原因。',
    'order-refund/already-refunded': '此申請已退款，不可再次操作。',
    'order-refund/reason-required': '請填寫退款調整原因。',
    'order-refund/amount-required': '請輸入有效的整數 VND 退款金額。',
    'order-refund/amount-must-be-positive': '目前後端尚未支援 0 元退款，請待後端更新後再操作。',
    'order-refund/amount-exceeds-refundable': '目前後端尚未支援超額補償，請待後端更新後再操作。',
}

export const cancellationErrorMessage = (error: unknown): string => {
    const response = (error as { response?: { status?: number; data?: { code?: string } } })?.response
    if (response?.status === 403) return '沒有取消審核權限，請以 Admin 帳號登入。'
    if (response?.data?.code && errorMessages[response.data.code]) return errorMessages[response.data.code]
    return '操作未確認成功。請先重新載入訂單確認最新結果，再決定是否重試。'
}
